<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_clothing_warehouse_access();$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$s=$pdo->prepare("SELECT m.*,p.product_code,p.product_name FROM stock_movements m JOIN products p ON p.id=m.product_id WHERE DATE(m.created_at) BETWEEN ? AND ? ORDER BY m.created_at DESC");$s->execute([$from,$to]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);$inCost=0;$revenue=0;$costOfSales=0;foreach($rows as $r){if($r['movement_type']==='Inbound')$inCost+=(float)$r['quantity']*(float)$r['unit_cost'];if(in_array($r['movement_type'],['Outbound','Picking'],true)){$revenue+=(float)$r['quantity']*(float)$r['selling_price'];$costOfSales+=(float)$r['quantity']*(float)$r['unit_cost'];}}$profit=$revenue-$costOfSales;$page_title='Inventory Profit Report';require __DIR__.'/../includes/header.php';?><div class="d-flex justify-content-between mb-4"><div><h1 class="page-heading"><?=e(t('inventory_reports'))?></h1><p class="page-subtitle mb-0"><?=current_language()==='zh'?'根据已记录的入库、出库和拣货作业计算预计毛利润。':'Estimated gross profit based on recorded inbound, outbound, and picking movements.'?></p></div><button class="btn btn-outline-secondary" onclick="window.print()"><i class="bi bi-printer"></i> <?=e(t('print_report'))?></button></div><div class="panel mb-4"><form class="row g-2"><div class="col-md-3"><label class="form-label"><?=e(t('date_from'))?></label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div class="col-md-3"><label class="form-label"><?=e(t('date_to'))?></label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-dark w-100"><?=e(t('filter'))?></button></div></form></div><div class="row g-3 mb-4"><div class="col-md-4"><div class="metric-card"><div class="metric-number">$<?=number_format($inCost,2)?></div><div class="metric-label"><?=e(t('inventory_cost'))?> (<?=e(t('inbound'))?>)</div></div></div><div class="col-md-4"><div class="metric-card"><div class="metric-number">$<?=number_format($revenue,2)?></div><div class="metric-label"><?=e(t('sales_revenue'))?> (<?=e(t('outbound'))?> / <?=e(t('picking'))?>)</div></div></div><div class="col-md-4"><div class="metric-card"><div class="metric-number text-success">$<?=number_format($profit,2)?></div><div class="metric-label"><?=e(t('gross_profit'))?></div></div></div></div><div class="panel table-responsive"><h2 class="h6 mb-3"><?=e(t('profit_by_movement'))?></h2><table class="table"><thead><tr><th><?=e(t('date'))?></th><th><?=e(t('product_name'))?></th><th><?=e(t('movement_type'))?></th><th><?=e(t('quantity'))?></th><th><?=e(t('unit_cost'))?></th><th><?=e(t('selling_price'))?></th><th><?=e(t('sales_revenue'))?></th><th><?=e(t('gross_profit'))?></th></tr></thead><tbody><?php foreach($rows as $r):$isSale=in_array($r['movement_type'],['Outbound','Picking'],true);$rowRevenue=$isSale?(float)$r['quantity']*(float)$r['selling_price']:0;$rowProfit=$isSale?$rowRevenue-(float)$r['quantity']*(float)$r['unit_cost']:0;?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['product_code'].' — '.$r['product_name'])?></td><td><?=e(tv($r['movement_type']))?></td><td><?=number_format($r['quantity'],2)?></td><td>$<?=number_format($r['unit_cost'],2)?></td><td>$<?=number_format($r['selling_price'],2)?></td><td>$<?=number_format($rowRevenue,2)?></td><td class="<?= $rowProfit>0?'text-success':''?>">$<?=number_format($rowProfit,2)?></td></tr><?php endforeach?></tbody></table></div><?php require __DIR__.'/../includes/footer.php'; ?>
